inline void ObserverGraph::addNode(const NodePtr &node) noexcept {
    REACTION_REGISTER_THREAD();
    ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
    m_observerList.insert({node, std::ref(node->m_observers)});
