void bindField(uint64_t id, const NodePtr &objPtr) {
        NodeSet nodesToBind;
        if (!m_fieldMap.contains(id)) {
            return;
        }
        nodesToBind = m_fieldMap[id]; // Copy the set

        // Bind nodes
        for (auto &node : nodesToBind) {
            ObserverGraph::getInstance().addObserver(objPtr, node.lock());
        }
    }

